  ('osha-1910-269-power', '1910.269 - Electric power generation, transmission, and distribution. | Occupational Safety and Health Administration', 'Occupational Safety and Health Administration', 'https://www.osha.gov', 'Engineering', 'Beginner', 6, 'English', 'https://www.osha.gov/laws-regs/regulations/standardnumber/1910/1910.269', 'free', 'Free public OSHA regulation text for 29 CFR 1910.269.', 'tutorial', 'OSHA electric power generation, transmission and distribution standard: electrical safe work practices, grounding and protective equipment.', true, '2026-10-30T00:00:00Z'),
